const base = "http://the VM's public address:18082";
for (const p of ["/v1/disbursements", "/v2/disbursements?limit=3"]) {
  const r = await fetch(base + p);
  const t = await r.text();
  console.log(p, r.status, t.slice(0, 2000));
}

