import json, urllib.request, urllib.parse, time
base='http://the VM's public address:18082'
def amount(url,id):
    p=json.load(urllib.request.urlopen(url))
    return [d['amount_cents'] for d in p['disbursements'] if d['id']==id]
for i in range(3):
    a=amount(base+'/v2/disbursements?limit=100','ds_00100')
    p=json.load(urllib.request.urlopen(base+'/v2/disbursements?limit=100'))
    c=p['cursor']
    b=amount(base+'/v2/disbursements?limit=100&cursor='+urllib.parse.quote(c),'ds_00100')
    v=amount(base+'/v1/disbursements','ds_00100')
    print(i,'p1',a,'p2first',b,'v1',v)
    time.sleep(2)
# inspect all boundary diffs p1last vs nextfirst vs v1
v1={d['id']:d for d in json.load(urllib.request.urlopen(base+'/v1/disbursements'))['disbursements']}
p=json.load(urllib.request.urlopen(base+'/v2/disbursements?limit=100'))
fields=['merchant_id','amount_cents','currency','created_at']
for page in range(1,25):
    last=p['disbursements'][-1]
    firstnext=None
    if not p['drained']:
        q=json.load(urllib.request.urlopen(base+'/v2/disbursements?limit=100&cursor='+urllib.parse.quote(p['cursor'])))
        firstnext=q['disbursements'][0]
    if last['id']==(firstnext or {}).get('id'):
        diffs={f:(last[f],firstnext[f],v1[last['id']][f]) for f in fields if not (last[f]==firstnext[f]==v1[last['id']][f])}
        if diffs: print('page',page,last['id'],diffs)
    p=q if not p['drained'] else p
    if p['drained']: break
PY`;
